import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

interface MemberCardProps {
  member: {
    id: string;
    name: string;
    university: string;
    bio: string;
    skills: string[];
    profileImageUrl?: string;
    isOnline?: boolean;
  };
}

export default function MemberCard({ member }: MemberCardProps) {
  const [isConnecting, setIsConnecting] = useState(false);

  const handleConnect = async () => {
    setIsConnecting(true);
    // Simulate connection process
    setTimeout(() => {
      setIsConnecting(false);
    }, 1000);
  };

  const getInitials = (name: string) => {
    return name
      .split(' ')
      .map(part => part[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  const getSkillColor = (skill: string) => {
    const colors = [
      'bg-blue-100 text-blue-800',
      'bg-green-100 text-green-800',
      'bg-purple-100 text-purple-800',
      'bg-orange-100 text-orange-800',
      'bg-pink-100 text-pink-800',
      'bg-teal-100 text-teal-800',
      'bg-yellow-100 text-yellow-800',
    ];

    const index = skill.length % colors.length;
    return colors[index];
  };

  return (
    <Card className="border border-slate-200 hover:shadow-md transition-shadow">
      <CardContent className="p-6">
        <div className="flex items-start space-x-4">
          {/* Avatar */}
          <div className="relative">
            <Avatar className="w-15 h-15">
              <AvatarImage src={member.profileImageUrl} alt={member.name} />
              <AvatarFallback className="bg-gradient-to-br from-solana-purple to-solana-green text-white">
                {getInitials(member.name)}
              </AvatarFallback>
            </Avatar>

            {/* Online Status */}
            <div className="absolute -bottom-1 -right-1 flex items-center space-x-1">
              <div className={`w-3 h-3 rounded-full border-2 border-white ${
                member.isOnline ? 'bg-green-400' : 'bg-slate-400'
              }`}></div>
            </div>
          </div>

          {/* Member Info */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between mb-2">
              <h4 className="font-semibold text-slate-900 truncate" data-testid={`text-member-name-${member.id}`}>
                {member.name}
              </h4>
              <div className="flex items-center space-x-1 text-xs">
                <div className={`w-2 h-2 rounded-full ${
                  member.isOnline ? 'bg-green-400' : 'bg-slate-400'
                }`}></div>
                <span className="text-slate-500">
                  {member.isOnline ? 'Online' : 'Offline'}
                </span>
              </div>
            </div>

            <p className="text-sm text-slate-600 mb-2" data-testid={`text-member-university-${member.id}`}>
              {member.university}
            </p>

            <p className="text-sm text-slate-500 mb-4 line-clamp-2" data-testid={`text-member-bio-${member.id}`}>
              {member.bio}
            </p>

            {/* Skills */}
            <div className="flex items-center justify-between">
              <div className="flex flex-wrap gap-1">
                {member.skills.slice(0, 2).map((skill, index) => (
                  <Badge 
                    key={index}
                    variant="secondary" 
                    className={`text-xs px-2 py-1 ${getSkillColor(skill)}`}
                    data-testid={`badge-skill-${member.id}-${skill.toLowerCase()}`}
                  >
                    {skill}
                  </Badge>
                ))}
                {member.skills.length > 2 && (
                  <Badge variant="secondary" className="text-xs px-2 py-1 bg-slate-100 text-slate-600">
                    +{member.skills.length - 2}
                  </Badge>
                )}
              </div>

              <Button
                variant="ghost"
                size="sm"
                className="text-solana-purple hover:text-purple-700 hover:bg-purple-50 px-3 py-1"
                onClick={handleConnect}
                disabled={isConnecting}
                data-testid={`button-connect-member-${member.id}`}
              >
                {isConnecting ? 'Connecting...' : 'Connect'}
              </Button>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

client/src/components/events/event-card..content:
import { useMutation } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { isUnauthorizedError } from "@/lib/authUtils";
import { apiRequest, queryClient } from "@/lib/queryClient";

interface EventCardProps {
  event: {
    id: number;
    title: string;
    description?: string;
    shortDescription?: string;
    location?: string;
    date: string;
    startTime: string;
    endTime: string;
    imageUrl?: string;
    eventType: string;
    isFeatured?: boolean;
  };
  showFullDetails?: boolean;
}

export default function EventCard({ event, showFullDetails = false }: EventCardProps) {
  const { user } = useAuth();
  const { toast } = useToast();

  const rsvpMutation = useMutation({
    mutationFn: async (status: string) => {
      await apiRequest("POST", `/api/events/${event.id}/rsvp`, { status });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/events"] });
      queryClient.invalidateQueries({ queryKey: ["/api/events/featured"] });
      toast({
        title: "RSVP Confirmed!",
        description: "You've successfully registered for this event.",
      });
    },
    onError: (error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "Please log in to RSVP for events.",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "RSVP Failed",
        description: "Failed to register for event. Please try again.",
        variant: "destructive",
      });
    },
  });

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-IE', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  const formatTime = (timeString: string) => {
    return new Date(timeString).toLocaleTimeString('en-IE', {
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getEventTypeIcon = (type: string) => {
    switch (type) {
      case 'workshop':
        return 'fas fa-code';
      case 'hackathon':
        return 'fas fa-trophy';
      case 'meetup':
        return 'fas fa-users';
      case 'office_hours':
        return 'fas fa-question-circle';
      default:
        return 'fas fa-calendar';
    }
  };

  const getEventTypeColor = (type: string) => {
    switch (type) {
      case 'workshop':
        return 'bg-green-100 text-green-800';
      case 'hackathon':
        return 'bg-purple-100 text-purple-800';
      case 'meetup':
        return 'bg-blue-100 text-blue-800';
      case 'office_hours':
        return 'bg-yellow-100 text-yellow-800';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <Card className="border border-slate-200 hover:shadow-lg transition-shadow">
      <CardContent className="p-0">
        {/* Event Image */}
        {event.imageUrl && (
          <div className="aspect-video w-full overflow-hidden rounded-t-lg">
            <img 
              src={event.imageUrl}
              alt={event.title}
              className="w-full h-full object-cover"
            />
          </div>
        )}

        <div className="p-6">
          {/* Event Header */}
          <div className="flex items-start justify-between mb-4">
            <div className="flex items-center space-x-3">
              {event.isFeatured && (
                <Badge className="bg-solana-purple/10 text-solana-purple">
                  <i className="fas fa-star mr-1"></i>
                  Featured
                </Badge>
              )}
              <Badge className={`${getEventTypeColor(event.eventType)}`}>
                <i className={`${getEventTypeIcon(event.eventType)} mr-1`}></i>
                {event.eventType.replace('_', ' ').replace(/\b\w/g, l => l.toUpperCase())}
              </Badge>
            </div>
            <span className="text-sm text-slate-500">{formatDate(event.date)}</span>
          </div>

          {/* Event Title and Description */}
          <h3 className="text-xl font-bold text-slate-900 mb-3" data-testid={`text-event-title-${event.id}`}>
            {event.title}
          </h3>

